function renderSettings(){$('#extraSection').innerHTML=ui`<div class="settings-panel"><div class="setting-row"><div><h3>语言</h3><p>选择界面语言。</p></div><select id="languageMode" class="theme-mode-select" aria-label="界面语言"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select></div><div class="setting-row" data-settings-section="storage"><div><h3>本地数据</h3><p>收藏和观看记录保存在所选数据位置，可通过备份迁移。</p></div><span class="rating">本地存储</span></div><div class="setting-row"><div><h3>导出收藏</h3><p>下载收藏和观看记录的 JSON 备份。</p></div><button id="exportData">导出备份 ↗</button></div><div class="setting-row"><div><h3>导入收藏</h3><p>支持本应用备份或含 entries 的 AniShelf JSON。</p></div><button id="importData">导入备份 ↓</button></div><div class="setting-row"><div><h3>外观</h3><p>选择界面显示模式。</p></div><select id="themeMode" class="theme-mode-select" aria-label="外观模式"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></div><div class="setting-row" data-settings-section="about"><div><h3>关于 AniShelf 桌面版</h3><p>支持手动添加、TMDb 导入和本地存储。</p></div><a href="https://github.com/samuelhe52/AniShelf" target="_blank" rel="noopener" style="font-size:11px;color:var(--accent)">参考项目 ↗</a></div></div>`;$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,library,watchHistory:WatchHistory.exportRecords(),lists:AniLists.exportLists(),seriesArchive:typeof SeasonManager!=='undefined'?SeasonManager.archive():[]},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='anishelf-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t("收藏备份已导出"))};$('#importData').onclick=()=>$('#importFile').click();$('#languageMode').value=I18n.getLanguage();$('#languageMode').onchange=e=>I18n.setLanguage(e.target.value);$('#themeMode').value=themeMode;$('#themeMode').onchange=e=>setThemeMode(e.target.value)}
